(ns armate.archimate.core (:require [clojure.string :as s] [armate.archimate.collector :as clt] [armate.archimate.metamodel.derivation.core :as dcr] [armate.archimate.metamodel.meta :as mt] [armate.archimate.multi-graph :as mg] [armate.archimate.parser :as prr] [armate.archimate.viz.align.neighbours :as alg] [armate.archimate.viz.combiner :as viz] [armate.utils :as u]))
(defn get-stats [context] (let [relations (mg/get-relationships (:relations context)) groups (group-by (comp :derivate last) relations)] {:types (count (:types context)), :elements (count (:elements context)), :relations {:original (count (groups nil [])), :nesting (count (groups :nesting [])), :certain (count (groups :certain [])), :potential (count (groups :potential []))}, :lints (count (:lints context))}))
(defn analyze-file [file-path] (let [content (slurp file-path)] (if (empty? content) (throw (ex-info "File is empty" {:file-path file-path})) (prr/analyze-content content))))
(defn stat-file [file-path] (try (-> file-path analyze-file dcr/derivate-relations get-stats) (catch clojure.lang.ExceptionInfo e {:exception {:message (ex-message e), :data (ex-data e)}})))
(defn filter-relationships [predicate key context] (update context key (partial mg/filter-relationships predicate)))
(defn ungroup [context] (->> (:relations context) (mg/get-relationships) (reduce (fn [acc [from to rel]] (if (and (= :nesting (:derivate rel)) (not= :grouping (get-in context [:elements from :kind]))) (-> (assoc-in acc [:elements to :in] nil) (update-in [:relations from to] u/fnil-conj-set (dissoc rel :derivate))) (update-in acc [:relations from to] u/fnil-conj-set rel))) (assoc context :relations {}))))
(defn erase-unbinded-elements [context] (let [forward-graph (:relations context) reverse-graph (mg/reverse-graph forward-graph)] (-> context (dissoc :connectors) (update :elements (fn* [%1] (->> (filter (fn [[alias _]] (or (forward-graph alias) (reverse-graph alias))) %1) (into {})))))))
(defn add-suffix [file-path name-suffix] (let [parts (s/split file-path #"\b\.\b") head (drop-last parts) ext (last parts)] (str (apply str head) name-suffix "." ext)))
(defn generate-derivate-file [predicate file-path name-suffix] (try (let [cut-ctx (->> (analyze-file file-path) (ungroup) (dcr/derivate-relations) (filter-relationships predicate :relations) (erase-unbinded-elements))] (->> (filter-relationships (fn [[f t _]] (and (get-in cut-ctx [:elements f]) (get-in cut-ctx [:elements t]))) :hidden cut-ctx) (alg/append-hidden-aligns) (viz/on-fly-generate-puml) (spit (add-suffix file-path name-suffix)))) (catch clojure.lang.ExceptionInfo e {:msg (ex-message e), :data (ex-data e)})))
(comment)
